"use strict";
const kioskReads=[
 {id:'last-bus',kind:'故事阅读',title:'末班车上的两张票',subtitle:'一个车站，一个被误会了很多年的约定',image:'images/memories/station.jpg',paragraphs:[
 '县城末班车总在晚上九点四十出发。老周卖了二十多年车票，记得车门上每一道划痕，却总记不住新来的乘务员。小林到站里上班的第一天，就听见人说：靠窗的第五排，别卖给别人。那是老周给一个从来不来的客人留的位置。',
 '小林不信。往后十几天，他看见老周每天都从抽屉里取两张票，一张塞进自己上衣口袋，一张放在售票窗边。旅客来问，老周就把窗边那张推过去，说今天这张已经有人买过了，你拿着吧。小林以为是站里给熟人的照顾，直到有一天，拿走车票的是一个提着化肥袋的陌生老人。',
 '老人翻遍口袋，只摸出几枚硬币，脸红得像喝过酒。老周没问他差多少，只说有人退了一张票，正好顺路。车开以后，小林忍不住问：天天都有人退票？老周擦着桌子，说做生意，总有凑巧的时候。话是这么说，可当晚核对账本，小林发现差的票钱全从老周自己的饭钱里补了。',
 '雨季来了。某天车快开了，一个穿黑夹克的男人冲进来，指着第五排说这是我的位置。小林以为终于等到那个神秘客人，赶紧叫老周。男人却把一个纸袋放在窗口，里面全是旧车票。有的边角已经磨白，有的背面写着日期。男人说自己小时候跟母亲坐过这趟车，母亲那次把钱弄丢了。',
 '原来十七年前，老周说有两张退票，让一对母子上了车。母亲后来一直想来还钱，身体却不好，没能走远。她把车票夹在户口本里，嘱咐儿子有机会一定要找到售票的人。男人打开纸袋，除了旧票，还有一封很短的信和一叠钱。老周盯着信看了半天，说不用还，那不是借。',
 '小林这才问起那两个从不离手的位置。老周笑了一下：我小时候也在车站丢过钱，一个卖票的人让我和父亲上车，说刚好有人退票。后来我来这里上班，没再见到那个人。车窗外雨很大，小林忽然明白，老周一直等的并不是某个会来还钱的客人。',
 '第二天晚上，窗边多了一只纸盒，写着“顺路票”。有人放一枚硬币，有人放一张完整车票，也有人只是把盒盖盖好，免得雨飘进去。第五排终于卖给了一个抱孩子的女人。小林问老周，不留了吗？老周说，留着呢。你看，整辆车不都坐着人吗。',
 '九点四十分，末班车拐过街角。售票窗口的灯还亮着，小林把账本合上，在纸盒里放进今天的第一张票。他没有写名字，只在背面画了一个小小的箭头，指向回家的方向。故事完。']},
 {id:'wrong-call',kind:'故事阅读',title:'打错的那通电话',subtitle:'彩屏亮起来的时候，有些话终于说出口',image:'images/memories/night.jpg',paragraphs:[
 '我买第一部手机的时候，通讯录里只有七个人。父亲的号码排在最后，因为我给他存的名字不是“爸”，而是“修车铺”。那年我们为选学校的事吵过一架，谁也不肯先服软，连电话铃响起来，都像一场还没有结束的争论。',
 '冬天的宿舍很冷，我把手机放在枕边，夜里忽然接到一个陌生号码。对方是个老人，开口就问：小勇，棉衣穿上没有？我说您打错了。他连声说对不起，却又问了一遍，这么晚还没睡，是不是屋里不暖和。我握着手机，莫名其妙地答了句，还行。',
 '后来这个号码又打来两次。第一次问饭吃得好不好，第二次说家里的橘子熟了。我每次都解释他打错了，可听到电话那头很轻的咳嗽声，总没能马上挂断。室友笑我，说你这是在给移动公司攒话费。我也笑，顺手把号码存成了“打错电话”。',
 '放假前一天，老人的声音格外高兴，说在路口看见一双鞋，觉得小勇穿着合适。我终于忍不住问，您怎么总打错？电话那头安静了一会儿，说儿子的号码换了，他把旧纸条上的两个数字认反了。每次听见年轻人应声，就想再多问一句。',
 '我问他为什么不让家里人重新写一遍。他说当然写了，新号码也在，只是有时候拿起电话，会先想起那个旧的。那一刻我没有再纠正他，坐在走廊尽头，告诉他我已经买好了回家的车票。老人说好，路上别睡得太沉，东西要看牢。',
 '挂断电话以后，我在通讯录里翻了很久。修车铺的号码其实很好记，小时候我在门口写作业，听父亲对每个顾客重复过无数次。我按下拨号，铃声只响一遍就接通了。父亲问，车坏了？我说没有，是我。又过了两秒，他才说，我知道。',
 '我本来准备了很多话，最后只问了句：家里冷不冷？父亲说炉子生着呢。接着我们像两个刚刚学会聊天的人，讨论车站、天气和那件我嫌旧却一直没扔的棉衣。谁都没提那场争吵，电话却没有像从前那样匆匆结束。',
 '回家那天，修车铺提前拉下了卷帘门。父亲站在站牌旁，手里提着一袋橘子。我把手机拿出来，悄悄改掉了一个联系人的名字。那个打错电话的老人后来没有再找过我，但每个冬天，我都会记得先给家里拨一通电话。故事完。']},
 {id:'borrowed-book',kind:'故事阅读',title:'借书卡背面的名字',subtitle:'找一本书，也找回一段没有说完的话',image:'images/memories/campus.jpg',paragraphs:[
 '学校旧图书室搬家那天，我被叫去帮忙整理书架。一本封面磨得发白的小说里，夹着一张蓝色借书卡。正面都是熟悉的借阅日期，背面却写着我的名字，字很小，最后一笔拖得很长。我盯着看了几秒，才想起那是当年坐在后排的许静的字。',
 '我们做过一年同桌。她看书很快，我却总是读到一半就忘了前面的情节。每次还书，她会问我读完没有。我说快了，她就把借书卡从书里抽出来，替我续一次。直到毕业，我还欠着那本书的最后两章，也欠她一句说好的读后感。',
 '卡片上有一条很淡的横线，下面写着：如果他来还书，请告诉他，结局没有那么坏。那时我家里出了些事，请假很久。回到学校，座位已经换过，许静转去了外地。我听见“转学”两个字，只觉得很多事总是这样，没等自己准备好，就已经结束。',
 '整理图书的老师认出了卡片，说她曾经来过一次，问那本书还在不在。具体哪年，老师也记不清了。我问她有没有留联系方式，老师摇头，又从抽屉里找出一本旧登记册。册子最后一页，有人用铅笔写着一个邮箱地址。',
 '我在网吧坐了半个小时，写了一封很短的邮件，说今天终于把最后两章读完了。发送以后，我才发现那本小说根本没有最后两章。过去记忆里那个阴沉的结局，原来只是自己读到一半时，急着替它安排的答案。',
 '几天后邮箱里多了一封回信。许静说她已经不太记得书里的细节，只记得有个同桌总把结局猜得很糟。她当时想说的，也不全是那本小说。邮件最后问我现在过得怎么样。我重新打开空白页面，这一次，终于没有只写“还行”。',
 '旧图书室后来成了一间音乐教室。那张借书卡没有再塞回小说里，我把它夹进自己的笔记本。每次翻到，都能看见背面那句字迹很淡的话。很多故事不是结局不好，只是我们在半路合上了书。故事完。']},
 {id:'repair-change',kind:'故事阅读',title:'找错的五块钱',subtitle:'一场发生在修理铺里的小误会',image:'images/memories/station.jpg',paragraphs:[
 '老陈修收音机，最怕别人催。小赵拿着一台只会沙沙响的收音机进店，问十分钟能不能修好。老陈没抬头，说十分钟可以修好你的着急，机器得慢慢看。小赵觉得这人说话有意思，便拉了张凳子坐在门口等。',
 '半小时以后，收音机终于唱起来。老陈收了十五块，找给小赵五块钱。小赵走到街口才想起自己刚才付的明明是二十，心里还夸老板算得清楚。可再摸口袋，五块钱变成了两张，总共十块。他赶紧折回去，说师傅，您多找了。',
 '老陈把台灯拧亮，看了看两张纸币，说多的那张不是我找的。小赵急了，难道我还能故意往自己口袋里塞钱？门口买菜的大婶凑过来，说你们俩别争，我刚看见一个穿校服的孩子在这儿弯了下腰。',
 '三个人找了一圈，孩子从隔壁文具店出来，手里攥着新买的橡皮。小赵问他是不是捡到钱了。孩子点头，说在门口捡到五块，以为是这个叔叔掉的，趁叔叔试收音机时塞进了外套口袋。小赵拍着脑门，连说怪不得。',
 '事情说清了，小赵把钱放到柜台上，让丢钱的人来认领。老陈却不肯，说这钱八成是我早上买零件时落的。两个人正推来推去，收音机忽然又没声了。小赵脸色一变，老陈也皱起眉，孩子凑过来，认真把音量旋钮往右转了半圈。',
 '歌声重新响起，店里安静了两秒，三个人一起笑出了声。小赵说，这五块给孩子当修理费吧。孩子想了一下，摇头说不要，我只是拧了一下。老陈把钱收进一只玻璃瓶，贴上“下次少收五块”的纸条。',
 '后来小赵每次从店门口经过，都会看一眼那只玻璃瓶。钱早就不在了，纸条却一直贴着。有次他问用到谁身上了，老陈说不记得了，反正不是修收音机的那个。小赵装作不满意，老陈指着旋钮说，要不再收你五块，给你教教这个怎么用？故事完。']},
 {id:'summer-style',kind:'时尚写真',title:'把一个夏天穿进照片里',subtitle:'原创图文：白衬衫、帆布包和有线耳机',image:'images/memories/portrait.jpg',paragraphs:[
 '拍照以前，先把衬衫的袖口挽到手肘。衣服不必很新，干净的颜色已经能让整张照片亮起来。那时候的数码相机没有多少滤镜，站到窗边或者树荫下，找一束柔和的光，就是最认真准备过的布景。',
 '帆布包里放着一本借来的书、一串钥匙和一副容易缠住的耳机。包带有一点褪色，反而像一个可以认出来的标记。搭配的乐趣不是凑齐同一张广告里的所有单品，而是让几件每天都在用的东西，忽然在今天看起来很合适。',
 '如果想留一点当年杂志图文的手感，可以把颜色减到两三种。白、蓝和一点暖色，已经足够。头发被风吹乱也不用急着重拍，回头看时，最像那个下午的照片，往往就是原来想删掉的一张。',
 '拍摄时把人放在画面的一边，给身旁的街道留一些位置。等很多年以后，那块招牌、一辆自行车或者一面旧墙，也会成为记忆的一部分。人像照片并不只记录一个人的样子，它还悄悄保存了那个人曾经生活过的地方。',
 '把最喜欢的一张存进手机，屏幕很小，细节不一定看得清。但每次亮屏都会见到熟悉的笑容。不要把图片压缩到只剩模糊的轮廓，也别为了修掉所有小缺点，最后连那个夏天的光都一起擦掉。',
 '这篇图文是本站原创穿搭与照片记忆随笔，人物为虚构成年人，配图为AI辅助创作，不是任何杂志的历史内页，也不是人物写真原片。愿它让你想起某张至今还舍不得删掉的照片。']},
 {id:'lost-phone',kind:'漫画',title:'雨停以前',subtitle:'原创四页短篇漫画 · 一部旧手机，接回一段失联的友情',comic:true,image:'images/reading/rain-comic.jpg',pages:[
 ['末班车刚刚开走，林小川在候车亭发现了一部手机。雨水落在屏幕上，蓝光还亮着。','“失主会回来找的吧？”他把手机包进干燥的纸袋，想起路口那家还没关门的修理铺。'],
 ['老师傅拆开后盖，发现电池旁夹着一张折了几次的小照片。年轻的三个人站在旧报刊亭前，笑得眼睛都眯起来。','照片背面没有电话，只写着一条早已改名的街。老师傅擦了擦眼镜：“这地方，我认得。”'],
 ['两个人沿街找过去，报刊亭的卷帘门已经落下。老师傅指着照片里戴帽子的人，说从前他们每天都在这里碰面。','正要离开，一个老人气喘吁吁地跑过来：“小伙子，看见一部手机没有？里面有一张不能丢的照片。”'],
 ['老师傅抬起头，老人也愣住了。隔着许多年的雨，他们终于认出了彼此。手机递回去时，两个人却先紧紧握住了手。','林小川撑开伞。三个人沿着河边慢慢走，雨还没有停，可谁也不再急着赶路。——完。']]} 
];
let kioskReadId=null,kioskReadPage=0,kioskNight=false,kioskFont=18;
const kioskRealCovers={story:{image:'images/magazine-covers/story-1994.jpg',date:'1994-05-01',label:'真实封面 · 1994年第5期',source:'https://collection.sina.com.cn/yjjj/2018-01-03/doc-ifyqcwaq7234781.shtml'},manke:{image:'images/magazine-covers/manke-early.jpg',date:'2006-02-01',label:'真实早期创刊号封面 · 以图面期号为准',source:'https://www.sohu.com/na/476237129_100193305'}};
function kioskCover(m){const c=kioskRealCovers[m.id];if(c&&c.date<=date)return c;return {image:m.kind==='漫画'?'images/posters/anime.jpg':m.kind==='时尚写真'?'images/memories/portrait.jpg':'images/memories/campus.jpg',label:'原创导览封面 · 非原刊封面',source:null};}
function kioskReadingList(m){return kioskReads.filter(r=>m.kind==='漫画'?r.kind==='漫画'||r.id==='borrowed-book':m.kind==='时尚写真'?r.kind==='时尚写真'||r.id==='wrong-call':r.kind==='故事阅读');}
function kioskReadingOpen(m,id){const list=kioskReadingList(m);kioskReadId=list.some(r=>r.id===id)?id:list[0].id;kioskReadPage=0;try{const n=Number(localStorage.getItem('archaeo-read-'+kioskReadId));if(Number.isInteger(n)&&n>=0&&n<20)kioskReadPage=n;}catch{}}
function kioskReadPages(r){if(r.comic)return r.pages;const pages=[];for(let i=0;i<r.paragraphs.length;i+=2)pages.push(r.paragraphs.slice(i,i+2));return pages;}
function renderKioskReading(m){const list=kioskReadingList(m);if(!list.some(r=>r.id===kioskReadId))kioskReadingOpen(m);const r=list.find(x=>x.id===kioskReadId),pages=kioskReadPages(r);kioskReadPage=Math.min(pages.length-1,Math.max(0,kioskReadPage));const cover=kioskCover(m);return `<section class="kiosk-reading ${kioskNight?'night':''}" style="--reading-font:${kioskFont}px"><div class="kiosk-reading-bar"><b>旧日阅读本</b><button data-kiosk-night>${kioskNight?'开灯':'熄灯'}</button><button data-kiosk-font="-1">A−</button><button data-kiosk-font="1">A＋</button><button data-kiosk-reading-menu>目录</button></div><div class="kiosk-reading-origin">${escapeHTML(m.name)} 阅读记忆 · 以下为本站原创作品，不是该杂志原文</div><div class="kiosk-reading-toc">${list.map(x=>`<button data-kiosk-read="${x.id}" class="${r.id===x.id?'selected':''}">${x.comic?'▣':'书'} ${x.title}</button>`).join('')}</div><article class="kiosk-paper"><small>POCKET READING / 原创夜读 ${r.comic?'漫画':'故事图文'}</small><h2>${r.title}</h2><p class="reading-subtitle">${r.subtitle}</p>${r.comic?`<div class="kiosk-comic-page" role="img" aria-label="雨停以前漫画第${kioskReadPage+1}页" style="background-position:${kioskReadPage%2?'100%':'0'} ${kioskReadPage>=2?'100%':'0'}"></div>`:kioskReadPage===0?`<img class="kiosk-reading-photo" src="${r.image}" alt="${r.title}原创怀旧配图">`:''}${pages[kioskReadPage].map(t=>`<p>${t}</p>`).join('')}<div class="kiosk-page-end">${kioskReadPage===pages.length-1?'全文完 · 谢谢你读到这里':'待续 · 按下一页继续'}<br>${kioskReadPage+1} / ${pages.length} 页</div></article><div class="kiosk-page-controls"><button data-kiosk-page="-1" ${kioskReadPage===0?'disabled':''}>‹ 上一页</button><span>第 ${kioskReadPage+1} 页</span><button data-kiosk-page="1" ${kioskReadPage===pages.length-1?'disabled':''}>下一页 ›</button></div><details class="kiosk-source-reading"><summary>查看真实封面与原刊阅读入口</summary><img src="${cover.image}" alt="${escapeHTML(m.name)}${cover.label}"><p>${cover.label}</p>${cover.source?`<a href="${cover.source}" target="_blank" rel="noopener noreferrer">封面出处 ↗</a>`:''}<p>本站原创内容和真实刊物分开标注。原刊阅读需要通过权利方，部分内容可能要求登录或订阅。</p>${m.id==='story'?'<a href="https://apps.apple.com/cn/app/id1097655732" target="_blank" rel="noopener noreferrer">《故事会》官方正版App与过刊说明 ↗</a>':m.id==='manke'?'<a href="https://www.zymk.cn/sort/28.html" target="_blank" rel="noopener noreferrer">知音漫客网正版漫画目录 ↗（当前平台）</a>':`<a href="${m.source}" target="_blank" rel="noopener noreferrer">刊物来源与阅读线索 ↗</a>`}</details></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-kiosk-read],[data-kiosk-page],[data-kiosk-night],[data-kiosk-font],[data-kiosk-reading-menu]');if(!b)return;const m=kioskAvailable().find(x=>x.id===kioskSelected);if(!m)return;e.preventDefault();if(b.dataset.kioskRead)kioskReadingOpen(m,b.dataset.kioskRead);if(b.dataset.kioskPage){const r=kioskReads.find(x=>x.id===kioskReadId);kioskReadPage=Math.max(0,Math.min(kioskReadPages(r).length-1,kioskReadPage+Number(b.dataset.kioskPage)));try{localStorage.setItem('archaeo-read-'+kioskReadId,String(kioskReadPage));}catch{}}if(b.hasAttribute('data-kiosk-night'))kioskNight=!kioskNight;if(b.dataset.kioskFont)kioskFont=Math.max(14,Math.min(26,kioskFont+Number(b.dataset.kioskFont)));navigate(current,false);if(b.hasAttribute('data-kiosk-reading-menu'))$('.kiosk-reading-toc')?.scrollIntoView({block:'center'});});
let phoneMagSelected=null,phoneMagRead=null,phoneMagPage=0;
function phoneMagazineMarkup(){const m=kioskMagazines.find(x=>x.id===phoneMagSelected&&x.from<=Number(year()));if(!m)return `<div class="phone-wap-title">旧日报刊亭 · ${year()}</div>${kioskAvailable().map(x=>`<button class="phone-mag-row" data-phone-magazine="${x.id}"><img src="${kioskCover(x).image}" alt="${escapeHTML(x.name)}封面图"><span>${escapeHTML(x.name)}<small>${x.kind} · 点开夜读</small></span></button>`).join('')}<small>部分封面为原创导览图，原刊来源见浏览器版。</small>`;const list=kioskReadingList(m),r=list.find(x=>x.id===phoneMagRead)||list[0],pages=r.comic?r.pages:r.paragraphs.map(p=>[p]);phoneMagPage=Math.max(0,Math.min(phoneMagPage,pages.length-1));return `<div class="phone-wap-title">${escapeHTML(m.name)} / 阅读记忆</div><button data-phone-mag-back>‹ 刊物列表</button><div class="phone-mag-toc">${list.map(x=>`<button data-phone-mag-read="${x.id}">${x.title}</button>`).join('')}</div><div class="phone-paper"><h2>${r.title}</h2><small>本站原创 · 非该杂志原文</small>${r.comic?`<div class="kiosk-comic-page" role="img" aria-label="原创漫画第${phoneMagPage+1}页" style="background-position:${phoneMagPage%2?'100%':'0'} ${phoneMagPage>=2?'100%':'0'}"></div>`:''}${pages[phoneMagPage].map(t=>`<p>${t}</p>`).join('')}<small>${phoneMagPage+1}/${pages.length} 页 · ${phoneMagPage===pages.length-1?'全文完':'按6看下一页'}</small><div class="phone-mag-controls"><button data-phone-mag-page="-1" ${phoneMagPage===0?'disabled':''}>4 上页</button><button data-phone-mag-page="1" ${phoneMagPage===pages.length-1?'disabled':''}>6 下页</button></div></div>`;}
function phoneMagazineKey(key){if(key==='4'||key==='6'){phoneMagPage=Math.max(0,phoneMagPage+(key==='6'?1:-1));refreshPhone();}else if(key==='2'||key==='8')$('#device-viewport').scrollBy({top:key==='2'?-100:100,behavior:'smooth'});else if(key==='0')phoneSelectApp('home');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-phone-magazine],[data-phone-mag-read],[data-phone-mag-page],[data-phone-mag-back]');if(!b)return;e.preventDefault();if(b.dataset.phoneMagazine){phoneMagSelected=b.dataset.phoneMagazine;phoneMagRead=null;phoneMagPage=0;}if(b.dataset.phoneMagRead){phoneMagRead=b.dataset.phoneMagRead;phoneMagPage=0;}if(b.dataset.phoneMagPage)phoneMagPage=Math.max(0,phoneMagPage+Number(b.dataset.phoneMagPage));if(b.hasAttribute('data-phone-mag-back'))phoneMagSelected=null;refreshPhone();});
